package com.gbkhealthcare.billing;
import java.math.BigDecimal;import java.time.LocalDateTime;import java.util.List;
public record InvoiceResponse(Long id,Long patientId,Long patientVisitId,String patientName,String invoiceNumber,LocalDateTime invoiceDate,BillingInvoice.Status status,BigDecimal subtotal,BigDecimal discountAmount,BillingInvoice.DiscountStatus discountStatus,BigDecimal taxAmount,BigDecimal total,BigDecimal paidAmount,BigDecimal outstandingAmount,List<InvoiceLineResponse> lines,List<PaymentResponse> payments,List<RefundResponse> refunds,List<AdjustmentResponse> adjustments){static InvoiceResponse from(BillingInvoice i,List<BillingInvoiceLine> lines,List<BillingPayment> payments,List<RefundResponse> refunds,List<BillingAdjustment> adjustments){String name=i.getPatientVisit().getPatient()==null?"Patient":i.getPatientVisit().getPatient().getFullName();return new InvoiceResponse(i.getId(),i.getPatientId(),i.getPatientVisit().getId(),name,i.getInvoiceNumber(),i.getInvoiceDate(),i.getStatus(),i.getSubtotal(),i.getDiscountAmount(),i.getDiscountStatus(),i.getTaxAmount(),i.getTotal(),i.getPaidAmount(),i.getOutstandingAmount(),lines.stream().map(InvoiceLineResponse::from).toList(),payments.stream().map(PaymentResponse::from).toList(),refunds,adjustments.stream().map(AdjustmentResponse::from).toList());}}
